  DELIMITER $$
 CREATE FUNCTION cantidad_de_alquileres (cliente INT)
 RETURNS INT
DETERMINISTIC
 BEGIN
 DECLARE  cantidad INT;
 SELECT COUNT(*) INTO cantidad
 FROM alquileres
 WHERE cliente_id = cliente;
 RETURN cantidad; 
 end
 $$
 
 SELECT cantidad_de_alquileres(1) AS cantidad_alquilada;
 
